import sys
def max_area(height: list[int]) -> int:
    left, right = 0, len(height) - 1; max_water = 0
    while left < right:
        current_water = min(height[left], height[right]) * (right - left)
        max_water = max(max_water, current_water)
        if height[left] < height[right]: left += 1
        else: right -= 1
    return max_water
if __name__ == "__main__": line = sys.stdin.read().strip(); print(max_area(list(map(int, line.split()))))

