import sys
def is_valid(s: str) -> bool:
    stack = []; mp = {")": "(", "}": "{", "]": "["}
    for char in s:
        if char in mp:
            top = stack.pop() if stack else '#'
            if mp[char] != top: return False
        else: stack.append(char)
    return not stack
