import sys
def coin_change(coins: list[int], amount: int) -> int:
    dp = [amount + 1] * (amount + 1); dp[0] = 0
    for i in range(1, amount + 1):
        for c in coins:
            if i >= c: dp[i] = min(dp[i], dp[i - c] + 1)
    return -1 if dp[amount] > amount else dp[amount]
if __name__ == "__main__": lines = sys.stdin.read().splitlines(); print(coin_change(list(map(int, lines[0].split())), int(lines[1])))
